import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/segments/';
export const segmentApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listSegments: build.query({
            query: ({ project, block }) => {
                const params = new URLSearchParams();
                if (project)
                    params.append('project', project.toString());
                if (block)
                    params.append('block', block.toString());
                params.append('without_pagination', '1');
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: [{ type: tags.SEGMENT, id: 'LIST' }],
        }),
        updateSegment: build.mutation({
            query(data) {
                // const { block_key, ...body } = data;
                // return {
                //   url: `${API_PATH}${block_key}`,
                //   method: 'PUT',
                //   body,
                // }
                // Updated to include block_key in the body as backend expects it
                return {
                    url: `${API_PATH}${data.block_key}`,
                    method: 'PUT',
                    body: data,
                };
            },
            invalidatesTags: [{ type: tags.SEGMENT, id: 'LIST' }],
        }),
        generateWorkInstanceAndSchedule: build.mutation({
            query(data) {
                return {
                    url: '/estimate/workinstance_and_schedule/',
                    method: 'POST',
                    body: data,
                };
            },
            invalidatesTags: [{ type: tags.SEGMENT, id: 'LIST' }],
        }),
    }),
});
export const { useListSegmentsQuery, useUpdateSegmentMutation, useGenerateWorkInstanceAndScheduleMutation, } = segmentApi;
